import heapq

def match(orders):
    trades = []
    # order book storage
    order_info = {}  # id -> {'side':..., 'price':..., 'qty':..., 'seq':..., 'active':bool}
    buy_heap = []   # entries: (-price, seq, id)
    sell_heap = []  # entries: (price, seq, id)

    def match_incoming(side, oid, price_limit, qty):
        """price_limit is None for market orders (any price)."""
        nonlocal trades
        remaining = qty
        if side == 'buy':
            heap = sell_heap
            while remaining > 0 and heap:
                p, seq, sid = heap[0]
                info = order_info.get(sid)
                if info is None or not info['active']:
                    heapq.heappop(heap)
                    continue
                if price_limit is not None and p > price_limit:
                    break
                heapq.heappop(heap)
                avail = info['qty']
                traded_qty = min(remaining, avail)
                trades.append([oid, sid, p, traded_qty])
                remaining -= traded_qty
                info['qty'] -= traded_qty
                if info['qty'] > 0:
                    heapq.heappush(heap, (p, seq, sid))
                else:
                    info['active'] = False
        else:  # side == 'sell'
            heap = buy_heap
            while remaining > 0 and heap:
                negp, seq, bid = heap[0]
                p = -negp
                info = order_info.get(bid)
                if info is None or not info['active']:
                    heapq.heappop(heap)
                    continue
                if price_limit is not None and p < price_limit:
                    break
                heapq.heappop(heap)
                avail = info['qty']
                traded_qty = min(remaining, avail)
                trades.append([bid, oid, p, traded_qty])
                remaining -= traded_qty
                info['qty'] -= traded_qty
                if info['qty'] > 0:
                    heapq.heappush(heap, (negp, seq, bid))
                else:
                    info['active'] = False
        return remaining

    for seq, order in enumerate(orders):
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            info = order_info.get(oid)
            if info is not None and info['active']:
                info['active'] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
            remaining = match_incoming(side, oid, price, qty)
            if remaining > 0:
                info = {'side': side, 'price': price, 'qty': remaining, 'seq': seq, 'active': True}
                order_info[oid] = info
                if side == 'buy':
                    heapq.heappush(buy_heap, (-price, seq, oid))
                else:
                    heapq.heappush(sell_heap, (price, seq, oid))
            else:
                # fully filled, still register as inactive record (optional)
                order_info[oid] = {'side': side, 'price': price, 'qty': 0, 'seq': seq, 'active': False}

        elif typ == 'ioc':
            _, oid, side, price, qty = order
            remaining = match_incoming(side, oid, price, qty)
            # discard remainder, register as inactive (fully consumed or partially)
            order_info[oid] = {'side': side, 'price': price, 'qty': remaining, 'seq': seq, 'active': False}

        elif typ == 'market':
            _, oid, side, qty = order
            remaining = match_incoming(side, oid, None, qty)
            order_info[oid] = {'side': side, 'price': None, 'qty': remaining, 'seq': seq, 'active': False}

    return trades

